module Global_module = Global_module

module Name = Global_module.Name

let test () =
  let name = Name.of_parameter_name in
  Format.printf "UTILITIES@.";

  (* Optionals *)
  let module Option = struct
    let print ppf lit = Format.fprintf ppf "%a" (fun ppf () -> Format.pp_print_string ppf lit) ()
  end in
  ()

let () =
  test ()

(** Tests for the [Global_module] library.  These cover the unit types and
    functions of the library, in particular substitution behaviour, validation,
    completeness checks and printing. *)

module Example = struct
  (* Convenience wrappers for building the test cases. *)
  module Name = Global_module.Name

  let parameter = Name.of_parameter_name

  let name ?(args = []) head = Name.create_exn head args

  let global ?(visible = []) ?(hidden = []) head =
    Global_module.create_exn head visible ~hidden_args:hidden

  let ( let* ) = Result.bind

  let subst = function
    | [] -> Global_module.Name.Map.empty
    | l ->
      List.fold_left
        (fun map (name, value) -> Global_module.Name.Map.add name value map)
        Global_module.Name.Map.empty l

  let print_name name = Format.printf "%s@." (Name.to_string name)

  let print_global global = Format.printf "%a@." Global_module.print global

  let print_bool b = Format.printf "%b@." b

  let print_result ok = print_bool ok
end

open Example

let () =
  Format.printf "Testing the Name module:@.";
  print_name (name "Foo");
  print_name (name ~args:[ parameter "X", name "A"; parameter "Y", name "B" ] "M");
  print_name (name ~args:[ parameter "X", name "Foo" ] "Y");
  Format.printf "@.";
  Format.printf "Testing the main type:@.";
  print_global (global "Foo");
  print_global (global ~visible:[ parameter "X", global "Foo" ] "M");
  print_global (global ~hidden:[ parameter "Y" ] "M");
  print_global
    (global
       ~visible:[ parameter "X", global "Foo" ]
       ~hidden:[ parameter "Y" ]
       "M");
  print_global
    (global
       ~visible:[ parameter "X", global ~hidden:[ parameter "Baz" ] "Foo" ]
       ~hidden:[ parameter "Y" ]
       "M");
  Format.printf "@.";
  Format.printf "Testing substitution with the root not being substituted:@.";
  let t = global ~visible:[ parameter "X", global "Foo" ] "M" in
  let t_subst =
    global
      ~visible:
        [ parameter "X", global ~visible:[ parameter "A", global "Q" ] "Foo" ]
      "M"
  in
  let result, changed = Global_module.subst t (subst [ parameter "X", global "Q" ]) in
  Format.printf "expected: %a@." Global_module.print t_subst;
  Format.printf "got:      %a@." Global_module.print result;
  print_bool (Global_module.equal t_subst result);
  print_result (changed = `Changed);
  Format.printf "@.";
  Format.printf
    "Testing substitution where a hidden argument becomes visible:@.";
  let t = global ~hidden:[ parameter "Y" ] "M" in
  let t_subst = global ~visible:[ parameter "Y", global "Foo" ] "M" in
  let result, changed = Global_module.subst t (subst [ parameter "Y", global "Foo" ]) in
  Format.printf "expected: %a@." Global_module.print t_subst;
  Format.printf "got:      %a@." Global_module.print result;
  print_bool (Global_module.equal t_subst result);
  print_result (changed = `Changed);
  Format.printf "@.";
  Format.printf
    "Testing substitution where no change occurs:@.";
  let t = global ~visible:[ parameter "X", global "Foo" ] "M" in
  let result, changed = Global_module.subst t (subst [ parameter "X", global "Q" ]) in
  Format.printf "result: %a@." Global_module.print result;
  print_result (Global_module.equal t result);
  print_result (changed = `Did_not_change);
  Format.printf "@.";
  Format.printf "Testing substitution with substitution of the root:@.";
  let t = parameter "X" in
  let t' = global "Foo" in
  let result, changed = Global_module.subst t (subst [ parameter "X", global "Foo" ]) in
  Format.printf "expected: %a@." Global_module.print t';
  Format.printf "got:      %a@." Global_module.print result;
  print_bool (Global_module.equal t' result);
  print_result (changed = `Changed);
  Format.printf "@.";
  Format.printf "Testing [subst_inside]:@.";
  let t = global ~visible:[ parameter "X", global "Foo" ] "M" in
  let t_subst =
    global ~visible:[ parameter "X", global ~visible:[ parameter "A", global "Q" ] "Foo" ] "M"
  in
  let result = Global_module.subst_inside t (subst [ parameter "X", global "Q" ]) in
  Format.printf "expected: %a@." Global_module.print t_subst;
  Format.printf "got:      %a@." Global_module.print result;
  print_bool (Global_module.equal t_subst result);
  Format.printf "@.";
  Format.printf "Testing [check]:@.";
  let s = subst [ parameter "X", global "Foo" ] in
  print_bool (Global_module.check s [ parameter "X"; parameter "Y" ]);
  print_bool (not (Global_module.check s [ parameter "Y" ]));
  Format.printf "@.";
  Format.printf "Testing [complete]:@.";
  print_bool (Global_module.complete (global "Foo"));
  print_bool (Global_module.complete (global ~visible:[ parameter "X", global "Foo" ] "M"));
  print_bool
    (not
       (Global_module.complete
          (global ~visible:[ parameter "X", global ~hidden:[ parameter "Y" ] "M" ] "M")));
  print_bool (not (Global_module.complete (global ~hidden:[ parameter "Y" ] "M")));
  Format.printf "@.";
  Format.printf "Testing [to_name]:@.";
  let t = global ~visible:[ parameter "X", global "Foo" ] ~hidden:[ parameter "Y" ] "M" in
  print_name (Global_module.to_name t);
  Format.printf "@.";
  Format.printf "Testing [all_args]:@.";
  let t = global ~visible:[ parameter "X", global "Foo" ] ~hidden:[ parameter "Y" ] "M" in
  List.iter
    (fun (param, value) ->
      Format.printf "%s := %a@." (Name.to_string param) Global_module.print value)
    (Global_module.all_args t)

module G = Global_module
module Name = G.Name

let name ?args head =
  match args with
  | None -> Name.create_no_args head
  | Some args -> Name.create_exn head args

let global ?(visible = []) ?(hidden = []) head : G.t =
  G.create_exn head visible ~hidden_args:hidden

let print_name n = Format.printf "%s@." (Name.to_string n)

let print_global g = Format.printf "%a@." G.print g

let print_labeled label f x =
  Format.printf "%s: %a@." label f x

let () =
  (* Name construction and printing *)
  print_labeled "name [no args]" Name.print (name "Foo");
  print_labeled "name [some args]" Name.print
    (name ~args:[ name "X", name "A"; name "Y", name "B" ] "M");
  print_labeled "name [parameterised arg]" Name.print
    (name ~args:[ name "X", name ~args:[ name "X", name "Foo" ] "Y" ] "M");

  (* Global construction and printing *)
  print_labeled "global [no args]" G.print (global "Foo");
  print_labeled "global [visible]" G.print
    (global ~visible:[ name "X", global "A" ] "M");
  print_labeled "global [hidden]" G.print
    (global ~hidden:[ name "X" ] "M");
  print_labeled "global [visible and hidden]" G.print
    (global ~visible:[ name "X", global "A" ] ~hidden:[ name "Y" ] "M");

  (* Names of parameters must be unique (and arguments are sorted). *)
  begin match
    Name.create "M" [ name "Y", name "B"; name "X", name "A" ]
  with
  | Ok _ -> Format.printf "Name.create [sorted args]: OK@."
  | Error (Duplicate _) -> Format.printf "Name.create [sorted args]: ERROR@."
  end;
  begin match
    Name.create "M" [ name "X", name "A"; name "X", name "B" ]
  with
  | Ok _ -> Format.printf "Name.create [duplicate]: OK@."
  | Error (Duplicate _) -> Format.printf "Name.create [duplicate]: ERROR@."
  end;
  begin match
    G.create "M" [ name "X", global "A" ] ~hidden_args:[ name "X" ]
  with
  | Ok _ -> Format.printf "G.create [visible/hidden clash]: OK@."
  | Error (Duplicate _) -> Format.printf "G.create [visible/hidden clash]: ERROR@."
  end;

  (* Substitution *)
  Format.printf "@[<v 2>SUBSTITUTION@,";

  (* Substitution yields the value when the global is a parameter. *)
  let s1 =
    G.create_exn "M" [ name "X", G.create_no_args "B" ] ~hidden_args:[] in
  let subst1 = Name.Map.of_list [ name "X", G.create_no_args "B" ] in
  let () =
    print_global s1;
    print_global (G.subst s1 subst1)
  in
  ()

let () = test ()

module Global_module = Global_module

module Name = Global_module.Name

(* This test is for the [Global_module] library, which is for computing what a
   module's remaining parameters look like when that module is referenced with
   a subset of its parameters already given.  Since parameters can themselves
   be parameterised, the proper handling of such substitutions is non-trivial.
   See the documentation in [global_module.mli] for more details. *)

(* Helpers for making the test cases more readable. *)

let name ?args head =
  match args with
  | None -> Name.create_no_args head
  | Some args -> Name.create_exn head args

let global ?(visible = []) ?(hidden = []) head =
  Global_module.create_exn head visible ~hidden_args:hidden

let print_name name = Format.printf "%s@." (Name.to_string name)

let print_global global = Format.printf "%a@." Global_module.print global

let print_name_labeled label name =
  Format.printf "%s: %a@." label Name.print name

let print_global_labeled label global =
  Format.printf "%s: %a@." label Global_module.print global

let print_subst result changed expected : unit =
  let changed =
    match changed with
    | `Changed -> "changed"
    | `Did_not_change -> "did not change"
  in
  Format.printf "actual: %a (%s)@." Global_module.print result changed;
  Format.printf "expected: %a@." Global_module.print expected;
  begin match compare result expected with
  | 0 -> Format.printf "OK@."
  | _ -> Format.printf "FAILED@."
  end

let () =
  Format.printf "@[<v 0>";
  Format.printf "@,@[<v 2>NAMES@,";

  (* Names *)
  print_name_labeled "no arguments" (name "Foo");
  print_name_labeled "some arguments" (name ~args:[ name "X", name "A" ] "M");
  print_name_labeled "argument with an argument" (name ~args:
    [ name "X", name ~args:[ name "X", name "Foo" ] "M" ] "Y");
  print_name_labeled "multiple arguments"
    (name ~args:[ name "A", name "B"; name "D", name "C" ] "M");

  Format.printf "@,Construction: uniqueness of argument names:";
  begin match
    Name.create "M" [ name "X", name "A"; name "X", name "B" ]
  with
  | Ok _ -> Format.printf " OK@."
  | Error (Duplicate _) -> Format.printf " Duplicate name@."
  end;
  begin match
    Name.create "M" [ name "X", name "A" ] with
  | Ok _ -> Format.printf "OK@."
  | Error (Duplicate _) -> Format.printf "Duplicate name@."
  end;

  Format.printf "@]";

  Format.printf "@,@[<v 2>GLOBALS@,";

  print_global_labeled "no arguments" (global "Foo");
  print_global_labeled "visible argument" (global
    ~visible:[ name "X", global "A" ] "M");
  print_global_labeled "hidden argument" (global
    ~hidden:[ name "X" ] "M");
  print_global_labeled "visible and hidden arguments" (global
    ~visible:[ name "X", global "A" ] ~hidden:[ name "Y" ] "M");
  print_global_labeled "hidden argument of a parameterised parameter value" (global
    ~visible:[ name "X", global ~hidden:[ name "Z" ] "Y" ] "M");

  Format.printf "@,Construction: uniqueness of argument names:";
  begin match
    Global_module.create "M" [ name "X", global "A" ]
      ~hidden_args:[ name "X" ]
  with
  | Ok _ -> Format.printf " OK@."
  | Error (Duplicate _) -> Format.printf " Duplicate name@."
  end;

  Format.printf "@]";

  Format.printf "@,@[<v 2>SUBSTITUTION@,";

  (* [subst] is defined on the elaborated [t], with a map from parameter names
     to their values.  At the top level, a fully elaborated module whose
     parameters are all filled in does not change.  *)
  let m = global ~visible:[ name "X", global "A" ] ~hidden:[ name "Y" ] "M" in
  let subst1 =
    Global_module.make_subst [ name "X", global "A" ]
  in
  let result, changed = Global_module.subst m subst1 in
  print_subst result changed m;

  Format.printf "@]";
  Format.printf "@]@."

(* This file is part of the tests for the [Global_module] library. *)

module Global_module = Global_module

module Name = Global_module.Name

let test () =
  let name ?args head =
    match args with
    | None -> Name.create_no_args head
    | Some args -> Name.create_exn head args
  in
  let global ?(visible = []) ?(hidden = []) head =
    Global_module.create_exn head visible ~hidden_args:hidden
  in
  let print_name name = Format.printf "%s@." (Name.to_string name) in
  let print_global global = Format.printf "%a@." Global_module.print global in
  let print_bool b = Format.printf "%b@." b in
  let print_subst_result ?(expects_change = true) ~expected ~actual ~changed =
    Format.printf "expected: %a@." Global_module.print expected;
    Format.printf "actual:   %a@." Global_module.print actual;
    Format.printf "equal:    %b@." (Global_module.equal expected actual);
    Format.printf "changed:  %b (expects change: %b)@."
      (match changed with `Changed -> true | `Did_not_change -> false)
      expects_change
  in

  (* -- Name construction and printing -- *)
  Format.printf "@[<v>Names@;@;";
  Format.fprintf Format.std_formatter "%s" "  ";
  print_name (name "Foo");
  print_name (name ~args:[ name "X", name "A"; name "Y", name "B" ] "M");
  print_name (name ~args:[ name "X", name "Foo" ] "Y");
  Format.printf "@]@;@;";

  (* -- Global construction and printing -- *)
  Format.printf "@[<v>Globals@;@;";
  print_global (global "Foo");
  print_global (global ~visible:[ name "X", global "A" ] "M");
  print_global (global ~hidden:[ name "X" ] "M");
  print_global
    (global ~visible:[ name "X", global "A" ] ~hidden:[ name "Y" ] "M");
  print_global
    (global
       ~visible:
         [ name "X", global ~hidden:[ name "Z" ] "A" ]
       ~hidden:[ name "Y" ]
       "M");
  Format.printf "@]@;@;";

  (* -- Smart constructors and invariants -- *)
  Format.printf "@[<v>Construction@;@;";
  (* The arguments get sorted by the smart constructor. *)
  print_global
    (global
       ~visible:[ name "Y", global "B"; name "X", global "A" ]
       "M");
  (* But there may not be two arguments with the same name. *)
  begin match
    Global_module.create "M" [ name "X", global "A"; name "X", global "A" ]
      ~hidden_args:[]
  with
  | Ok _ ->
      Format.printf "duplicate visible arguments: accepted@."
  | Error (Duplicate _) ->
      Format.printf "duplicate visible arguments: rejected@."
  end;
  begin match
    Global_module.create "M" [ name "X", global "A" ] ~hidden_args:[ name "X" ]
  with
  | Ok _ ->
      Format.printf "visible/hidden argument name clash: accepted@."
  | Error (Duplicate _) ->
      Format.printf "visible/hidden argument name clash: rejected@."
  end;
  begin match
    Global_module.Name.create "M" [ name "X", name "A"; name "X", name "B" ]
  with
  | Ok _ ->
      Format.printf "duplicate name arguments: accepted@."
  | Error (Duplicate _) ->
      Format.printf "duplicate name arguments: rejected@."
  end;
  Format.printf "@]@;@;";

  (* -- Substitution -- *)
  Format.printf "@[<v>Substitution@;@;";
  (* Simplest case: the whole global is a key of the substitution. *)
  let substituted =
    subst =
      Name.of_parameter_name "X",
      global "Foo" in
  let rhs_expected = global "Foo" in
  let result, changed =
    Global_module.subst (global ~hidden:[] "X")
      (Name.Map.singleton (Name.of_parameter_name "X") (global "Foo"))
  in
  print_subst_result ~expected:rhs_expected ~actual:result ~changed;
  Format.printf "@]@;@;";
  ()

let () = test ()

(** Tests for the [Global_module] library.  This library is for computing what
    a module's remaining parameters look like when that module is referenced
    with a subset of its parameters already given.  Since parameters can
    themselves be parameterised, the proper handling of such substitutions is
    non-trivial.  See [global_module.mli] for a more detailed description.

    The format of the output serves as a test of the printing of the various
    types in the library. *)

module Global_module = Global_module

module Name = Global_module.Name

(* Helpers for constructing test data. *)

let name ?args head : Name.t =
  match args with
  | None -> Name.create_no_args head
  | Some args -> Name.create_exn head args

let global ?(visible = []) ?(hidden = []) head : Global_module.t =
  Global_module.create_exn head visible ~hidden_args:hidden

(* Helpers for printing. *)

let print_name name = Format.printf "%s: %s@." "name" (Name.to_string name)

let print_global global = Format.printf "%s: %a@." "global" Global_module.print global

let print_parameter_name name = Format.printf "parameter name: %s@." (Name.to_string name)

(* Report the result of a substitution. *)

let print_subst_result (result, changed) expected =
  let changed =
    match changed with
    | `Changed -> "changed"
    | `Did_not_change -> "did not change"
  in
  Format.printf "subst: %a (%s)@." Global_module.print result changed;
  if Global_module.equal result expected
  then Format.printf "OK@."
  else (Format.printf "Expected: %a@." Global_module.print expected;
        assert false)

module Section = struct
  let header name = Format.printf "@[<v 2>>>> %s@." name
  let footer () = Format.printf "@]@."
end

let () =
  Section.header "Names";

  print_name (name "Foo");
  print_name (name ~args:[ name "X", name "A" ] "M");
  print_name (name ~args:[ name "X", name ~args:[ name "X", name "Foo" ] "Y" ] "M");
  print_name (name ~args:[ name "Y", name "B"; name "X", name "A" ] "M");

  print_parameter_name (Name.of_parameter_name "X");

  Section.footer ();

  Section.header "Globals (the elaborated form)";

  print_global (global "Foo");
  print_global (global ~visible:[ name "X", global "A" ] "M");
  print_global (global ~hidden:[ name "X" ] "M");
  print_global (global ~visible:[ name "X", global "A" ] ~hidden:[ name "Y" ] "M");
  print_global
    (global ~visible:[ name "X", global ~hidden:[ name "Z" ] "Y" ] "M");

  Section.footer ();

  Section.header "Construction: uniqueness and sorting";

  begin match
    Name.create "M" [ name "X", name "A"; name "X", name "B" ]
  with
  | Ok _ -> Format.printf "duplicate argument names: unexpectedly OK@."
  | Error (Duplicate { name; _ }) ->
    Format.printf "duplicate argument names reported: %s@." name
  end;

  begin match
    Name.create "M" [ name "X", name "A"; name "Q", name "B" ]
  with
  | Ok _ -> Format.printf "unique argument names: OK@."
  | Error (Duplicate _) -> Format.printf "unique argument names: unexpectedly duplicate@."
  end;

  begin match
    Global_module.create "M" [ name "X", global "A" ] ~hidden_args:[ name "X" ]
  with
  | Ok _ -> Format.printf "visible/hidden clash: unexpectedly OK@."
  | Error (Duplicate { name; _ }) ->
    Format.printf "visible/hidden clash reported: %s@." name
  end;

  Section.footer ();

  Section.header "Substitution";

  (* Substituting a value for a parameter that appears as a hidden argument
     "reveals" that argument. *)
  let t = global ~hidden:[ name "X" ] "M" in
  let expected = global ~visible:[ name "X", global "Foo" ] "M" in
  let result =
    Global_module.subst t
      (Name.Map.of_list [ name "X", global "Foo" ])
  in
  print_subst_result result expected;

  (* If the whole [t] is just a parameter name then it is replaced. *)
  let t = global "X" in
  let expected = global "Foo" in
  let result =
    Global_module.subst t
      (Name.Map.of_list [ name "X", global "Foo" ])
  in
  print_subst_result result expected;

  (* Substitution recurses into the values of visible arguments. *)
  let t = global ~visible:[ name "X", global "Y" ] "M" in
  let expected = global ~visible:[ name "X", global "B" ] "M" in
  let result =
    Global_module.subst t
      (Name.Map.of_list [ name "Y", global "B" ])
  in
  print_subst_result result expected;

  (* If the substitution does not apply then the result is unchanged. *)
  let t = global ~visible:[ name "X", global "Foo" ] "M" in
  let result =
    Global_module.subst t
      (Name.Map.of_list [ name "Y", global "B" ])
  in
  print_subst_result result t;

  (* [subst_inside] does not look at the root. *)
  let t = global "X" in
  let result =
    Global_module.subst_inside t
      (Name.Map.of_list [ name "X", global "Foo" ])
  in
  print_global result;

  Section.footer ();

  Section.header "[complete]";

  Format.printf "no arguments: %b@." (Global_module.complete (global "Foo"));
  Format.printf
    "visible arguments only: %b@."
    (Global_module.complete (global ~visible:[ name "X", global "Foo" ] "M"));

  (* [global "X"] is the parameter [X] as a global: even though it is not
     complete, it has no hidden arguments so [complete] returns true.  This
