(* This file contains tests for the [Global_module] library.  It is intended to
   be read in conjunction with [global_module_test.expected]. *)

module Global_module = Global_module

module Name = Global_module.Name

let test () =
  let name ?args head =
    match args with
    | None -> Name.create_no_args head
    | Some args -> Name.create_exn head args
  in
  let global ?(visible = []) ?(hidden = []) head =
    Global_module.create_exn head visible ~hidden_args:hidden
  in
  let param p = Name.of_parameter_name p in
  let print_name name = Format.printf "%s@." (Name.to_string name) in
  let print_global global = Format.printf "%a@." Global_module.print global in
  let print_bool b = Format.printf "%b@." b in
  let print_subst_result ~expected ~actual ~changed =
    Format.printf "expected: %a@." Global_module.print expected;
    Format.printf "actual:   %a@." Global_module.print actual;
    Format.printf "equal:    %b@." (Global_module.equal expected actual);
    Format.printf "changed:  %b@."
      (match changed with `Changed -> true | `Did_not_change -> false)
  in

  (* --- Construction and printing of names and globals --- *)
  Format.printf "@[<v 0>NAMES@;";
  print_name (name "Foo");
  print_name (name ~args:[ param "X", name "A" ] "M");
  print_name (name ~args:[ param "X", name ~args:[ param "X", name "Foo" ] "Y" ] "M");
  print_name (name ~args:[ param "Y", name "B"; param "X", name "A" ] "M");
  Format.printf "@]";
  Format.printf "@.";

  Format.printf "@[<v 0>GLOBALS@;";
  print_global (global "Foo");
  print_global (global ~visible:[ param "X", global "A" ] "M");
  print_global (global ~hidden:[ param "X" ] "M");
  print_global (global ~visible:[ param "X", global "A" ] ~hidden:[ param "Y" ] "M");
  print_global
    (global
       ~visible:[ param "X", global ~hidden:[ param "Z" ] "A" ]
       ~hidden:[ param "Y" ]
       "M");
  Format.printf "@]";
  Format.printf "@.";

  (* --- The smart constructors preserve the invariants --- *)

  Format.printf "@[<v 0>CONSTRUCTION@;";
  (* The arguments should be sorted even if given out of order. *)
  print_global
    (global ~visible:[ param "Y", global "B"; param "X", global "A" ] "M");
  (* ... but argument names must be unique given in the first place. *)
  begin match
    Name.create "M" [ param "X", name "A"; param "X", name "B" ]
  with
  | Ok _ ->
      Format.printf "duplicate name arguments: not rejected@."
  | Error (Duplicate _) ->
      Format.printf "duplicate name arguments: rejected@."
  end;
  begin match
    Global_module.create "M" [ param "X", global "A"; param "X", global "B" ]
      ~hidden_args:[]
  with
  | Ok _ ->
      Format.printf "duplicate visible arguments: not rejected@."
  | Error (Duplicate _) ->
      Format.printf "duplicate visible arguments: rejected@."
  end;
  begin match
    Global_module.create "M" [ param "X", global "A" ] ~hidden_args:[ param "X" ]
  with
  | Ok _ ->
      Format.printf "visible/hidden argument name clash: not rejected@."
  | Error (Duplicate _) ->
      Format.printf "visible/hidden argument name clash: rejected@."
  end;
  Format.printf "@]";
  Format.printf "@.";

  (* --- Substitution --- *)

  Format.printf "@[<v 0>SUBSTITUTION@;";

  (* If the whole thing is a parameter, the substitution returns the value. *)
  let t = global "X" in
  let subst = Name.Map.singleton (param "X") (global "Foo") in
  let expected = global "Foo" in
  let actual, changed = Global_module.subst t subst in
  print_subst_result ~expected ~actual ~changed;

  (* Substitution in a hidden argument makes it visible. *)
  let t = global ~hidden:[ param "X" ] "M" in
  let subst = Name.Map.singleton (param "X") (global "Foo") in
  let expected = global ~visible:[ param "X", global "Foo" ] "M" in
  let actual, changed = Global_module.subst t subst in
  print_subst_result ~expected ~actual ~changed;

  (* Substitution recurses into argument values. *)
  let t = global ~visible:[ param "X", global "Y" ] "M" in
  let subst = Name.Map.singleton (param "Y") (global "B") in
  let expected = global ~visible:[ param "X", global "B" ] "M" in
  let actual, changed = Global_module.subst t subst in
  print_subst_result ~expected ~actual ~changed;

  (* A substitution that does not apply leaves the value unchanged. *)
  let t =
    global ~visible:[ param "X", global "A" ] ~hidden:[ param "Y" ] "M" in
  let subst = Name.Map.singleton (param "Z") (global "B") in
  let expected = t in
  let actual, changed = Global_module.subst t subst in
  print_subst_result ~expected ~actual ~changed;

  (* [subst_inside] does not substitute the root. *)
  let t = global "X" in
  let subst = Name.Map.singleton (param "X") (global "Foo") in
  let result = Global_module.subst_inside t subst in
  print_global result;

  Format.printf "@]";
  Format.printf "@.";

  (* --- [complete] --- *)

  Format.printf "@[<v 0>COMPLETENESS@;";
  print_bool (Global_module.complete (global "Foo"));
  print_bool (Global_module.complete (global ~visible:[ param "X", global "A" ] "M"));
  print_bool (Global_module.complete (global ~visible:[ param "X", global "X" ] "M"));
  print_bool (Global_module.complete (global ~hidden:[ param "X" ] "M"));
  print_bool (Global_module.complete (global ~visible:[ param "X", global "X" ] ~hidden:[ param "Y" ] "M"));
  Format.printf "@]";
  Format.printf "@.";

  (* --- [to_name], [all_args] --- *)

  Format.printf "@[<v 0>TO_NAME AND ALL_ARGS@;";
  let t =
    global
      ~visible:[ param "X", global "Foo" ]
      ~hidden:[ param "Y" ]
      "M" in
  print_name (Global_module.to_name t);
  List.iter
    (fun (param, value) ->
      Format.printf "%s := %a@." (Name.to_string param) Global_module.print value)
    (Global_module.all_args t);
  Format.printf "@]";
  Format.printf "@."

let () = test ()

(* This file contains tests for the [Global_module] library.  It exercises the
   printing of the different kinds of values, the invariants maintained by the
   smart constructors, substitution behaviour (including "revealing"
   substitution), validation of substitutions, and completeness checks. *)

module Global_module = Global_module

module Name = Global_module.Name

let test () =
  let name ?args head =
    match args with
    | None -> Name.create_no_args head
    | Some args -> Name.create_exn head args
  in
  let global ?(visible = []) ?(hidden = []) head =
    Global_module.create_exn head visible ~hidden_args:hidden
  in
  let parameter = Name.of_parameter_name in
  let print_name name = Format.printf "%s@." (Name.to_string name) in
  let print_global global = Format.printf "%a@." Global_module.print global in
  let print_bool b = Format.printf "%b@." b in
  let print_subst_result ~expected ~actual ~changed =
    Format.printf "expected:  %a@." Global_module.print expected;
    Format.printf "actual:    %a@." Global_module.print actual;
    Format.printf "equal:     %b@." (Global_module.equal expected actual);
    Format.printf "changed:   %b@."
      (match changed with `Changed -> true | `Did_not_change -> false)
  in
  let subst l = Name.Map.of_list l in

  (* --- Name construction and printing --- *)
  Format.printf "NAMES@;";
  print_name (name "Foo");
  print_name (name ~args:[ parameter "X", name "A" ] "M");
  print_name
    (name ~args:[ parameter "X", name ~args:[ parameter "X", name "Foo" ] "M" ]
       "Y");
  print_name
    (name ~args:[ parameter "Y", name "B"; parameter "X", name "A" ] "M");
  Format.printf "%a@." Name.print (parameter "X");
  Format.printf "@.";

  (* --- Global construction and printing --- *)
  Format.printf "GLOBALS@;";
  print_global (global "Foo");
  print_global (global ~visible:[ parameter "X", global "A" ] "M");
  print_global (global ~hidden:[ parameter "X" ] "M");
  print_global
    (global
       ~visible:[ parameter "X", global "A" ]
       ~hidden:[ parameter "Y" ]
       "M");
  print_global
    (global
       ~visible:[ parameter "X", global ~hidden:[ parameter "Z" ] "Y" ]
       "M");
  Format.printf "@.";

  (* --- Smart constructors: sorting and uniqueness --- *)
  Format.printf "SMART CONSTRUCTORS@;";
  (* Arguments are sorted by name. *)
  print_global
    (global
       ~visible:
         [ parameter "Y", global "B"; parameter "X", global "A" ]
       "M");
  print_name
    (name ~args:[ name "Y", name "B"; name "X", name "A" ] "M");
  (* ... but names must be unique. *)
  let result = Name.create "M" [ name "X", name "A"; name "X", name "B" ] in
  print_bool (match result with Ok _ -> false | Error (Duplicate _) -> true);
  let result =
    Global_module.create "M" [ parameter "X", global "A"; parameter "X", global "B" ]
      ~hidden_args:[]
  in
  print_bool (match result with Ok _ -> false | Error (Duplicate _) -> true);
  (* ... including clashes between visible and hidden arguments. *)
  let result =
    Global_module.create "M" [ parameter "X", global "A" ]
      ~hidden_args:[ parameter "X" ]
  in
  print_bool (match result with Ok _ -> false | Error (Duplicate _) -> true);
  print_bool
    (match Global_module.create "M" [ parameter "X", global "A" ]
            ~hidden_args:[ parameter "Y" ]
     with
    | Ok _ -> true
    | Error (Duplicate _) -> false);
  Format.printf "@.";

  (* --- Substitution --- *)
  Format.printf "SUBSTITUTION@;";

  (* If the global is simply a parameter then the substitution plays no role
     in the result other than giving the corresponding value. *)
  let t = global "X" in
  print_global t;
  let expected = global "Foo" in
  let result =
    Global_module.subst t (subst [ parameter "X", global "Foo" ])
  in
  print_subst_result ~expected ~actual:(fst result) ~changed:(snd result);

  (* Hidden arguments may be "revealed": if the value of a hidden argument is
     itself a parameter that is a key of the substitution then it becomes a
     visible argument. *)
  let t = global "M" ~hidden:[ parameter "X" ] in
  print_global t;
  let expected = global "M" ~visible:[ parameter "X", global "Foo" ] in
  let result =
    Global_module.subst t (subst [ parameter "X", global "Foo" ])
  in
  print_subst_result ~expected ~actual:(fst result) ~changed:(snd result);

  (* The substitution is applied to the values of visible arguments too. *)
  let t = global "M" ~visible:[ parameter "X", global "Y" ] in
  print_global t;
  let expected = global "M" ~visible:[ parameter "X", global "B" ] in
  let result =
    Global_module.subst t (subst [ parameter "Y", global "B" ])
  in
  print_subst_result ~expected ~actual:(fst result) ~changed:(snd result);

  (* If the substitution is not applicable then nothing changes. *)
  let t = global "M" ~visible:[ parameter "X", global "A" ] in
  print_global t;
  let result =
    Global_module.subst t (subst [ parameter "Y", global "B" ])
  in
  print_subst_result ~expected:t ~actual:(fst result) ~changed:(snd result);

  (* [subst_inside] applies the substitution in the arguments but leaves the
     global itself alone. *)
  let t = global "X" in
  let result =
    Global_module.subst_inside t (subst [ parameter "X", global "Foo" ])
  in
  print_global result;
  print_bool (Global_module.equal t result);
  Format.printf "@.";

  (* --- [check] --- *)
  Format.printf "CHECK@;";
  let s =
    subst [ parameter "X", global "Foo"; parameter "Y", global "Bar" ]
  in
  (* Every parameter in the substitution must be in the list. *)
  print_bool (Global_module.check s [ parameter "X"; parameter "Y" ]);
  print_bool (Global_module.check s [ parameter "X" ]);
  print_bool
    (Global_module.check
       (subst [ parameter "Z", global "Foo" ])
       [ parameter "X"; parameter "Y" ]);
  Format.printf "@.";

  (* --- [complete] --- *)
  Format.printf "COMPLETE@;";
  print_bool (Global_module.complete (global "Foo"));
  print_bool
    (Global_module.complete
       (global "M" ~visible:[ parameter "X", global "A" ]));
  print_bool (Global_module.complete (global "M" ~hidden:[ parameter "X" ]));
  print_bool
    (Global_module.complete
       (global "M"
          ~visible:[ parameter "X", global ~hidden:[ parameter "Z" ] "Y" ]));
  Format.printf "@.";

  (* --- [to_name] and [all_args] --- *)
  Format.printf "TO_NAME AND ALL_ARGS@;";
  let t =
    global "M"
      ~visible:[ parameter "X", global "Foo" ]
      ~hidden:[ parameter "Y" ]
  in
  print_global t;
  print_name (Global_module.to_name t);
  List.iter
    (fun (param, value) ->
      Format.printf "%s := %a@." (Name.to_string param) Global_module.print value)
    (Global_module.all_args t)

let () = test ()

